const CHEATS=[{"id": "black", "n": "Оверлей на чёрном фоне", "d": "оверлей — видео, которое кладут поверх ролика: блики, пыль, плёнка, засветки", "pc": 1, "ph": 1, "stepsPh": ["Добавь файл оверлея (наложения поверх видео) на отдельную дорожку: «Наложение» → «Добавить наложение».", "Растяни его двумя пальцами на весь кадр.", "«Смешивание» (режим наложения) → «Экран». Чёрный фон исчезнет, останутся только блики и частицы.", "Слишком ярко — убавь «Непрозрачность» до 60–80%."], "stepsPc": ["Положи оверлей на дорожку выше видео (V2, V3…).", "Панель «Элементы управления эффектами» → «Непрозрачность» → «Режим наложения» → «Экран».", "Если оверлей другого размера — плагин КК → «Исправить» → «Убрать чёрные рамки».", "Слишком ярко — убавь «Непрозрачность» до 60–80%.", "Быстрее всего — плагин КК → «Вставки»: оверлей встанет сразу с режимом «Экран»."]}, {"id": "green", "n": "Анимация на цветном фоне (хромакей)", "d": "хромакей — удаление однотонного фона, как «зелёный экран» в кино", "ph": 1, "stepsPh": ["Добавь файл поверх видео через «Наложение».", "«Удалить фон» → «Хромакей» (удаление однотонного фона).", "Пипеткой ткни в фон файла (зелёный или розовый). «Интенсивность» — около 20–30.", "Осталась цветная кайма по краям — подними «Тень» или «Края»."], "note": "У наборов «iOS», «Технологичный», «Ретро», «Мультяшный», «Природа» и «Сезонные» фон розовый, у остальных — зелёный: в самих элементах этих наборов есть зелёный цвет. Пипеткой выбирай тот цвет фона, который видишь."}, {"id": "alpha", "n": "Прозрачные видео (MOV) в Премьере", "d": "MOV с прозрачностью — видео без фона, кладётся прямо поверх ролика", "pc": 1, "stepsPc": ["Перетащи файл .mov из набора на дорожку выше видео — фон у него уже прозрачный.", "Переход ставь так, чтобы его середина пришлась точно на склейку (место, где один клип сменяет другой): в середине он закрывает кадр.", "Нужна другая длина — правый клик → «Скорость/Продолжительность» (Cmd/Ctrl+R).", "Удобнее всего — плагин КК → «Вставки»: файл сам встанет на плейхед (бегунок времени)."]}, {"id": "font", "n": "Свой шрифт на телефон и компьютер", "d": "iPhone, Android, Mac, Windows", "pc": 1, "ph": 1, "stepsPh": ["Скачай шрифт в формате .ttf или .otf (например, из подборки в стилевом наборе).", "CapCut: «Текст» → «Шрифт» → вкладка загруженных шрифтов → «Импорт» и выбери файл.", "Нет кнопки импорта в твоей версии — обнови CapCut. На iPhone шрифт можно поставить в систему через приложение-установщик шрифтов, на Android — открыть файл шрифта из «Загрузок».", "Проверь, что есть кириллица и латиница: напиши «Привет Hello»."], "stepsPc": ["Скачай .ttf или .otf.", "Mac: двойной клик по файлу → «Установить». Windows: правый клик → «Установить для всех пользователей».", "Перезапусти Премьер — шрифт появится в списке.", "Шрифты для титров и субтитров КК (Montserrat, Unbounded, JetBrains Mono) ставит установщик плагина."], "todo": "Название пункта импорта шрифта в CapCut на телефоне меняется от версии к версии."}, {"id": "frames", "n": "Чёрные рамки после стабилизации", "d": "стабилизация — программное «успокоение» трясущейся картинки", "pc": 1, "stepsPc": ["Выдели клип → «Эффекты» → «Стабилизатор деформации».", "Дождись анализа (полоска на клипе).", "«Кадрирование» → «Стабилизация, обрезка, автомасштаб» — края обрежутся, рамки уйдут.", "Кадр сильно увеличился и «поплыл» — снизь «Сглаживание» до 15–25%.", "В плагине КК это одна кнопка: «Исправить» → «Стабилизировать без рамок»."]}, {"id": "fixph", "n": "Исправить в CapCut", "d": "тряска, рамки, слоумо", "ph": 1, "stepsPh": ["Тряска: выдели клип → «Стабилизация» → «Рекомендуемая». Чем сильнее — тем больше кадр обрежется.", "Чёрные рамки: выдели клип и разведи двумя пальцами в окне просмотра, пока картинка не заполнит экран.", "Слоумо (замедление): «Скорость» → «Обычная» → 0,5x. Если есть «Плавное замедление» — включи.", "Мерцание от ламп в CapCut почти не лечится — смотри шпаргалку «Мерцание»."]}, {"id": "slowmo", "n": "Слоумо без рывков", "d": "замедление, которое выглядит дорого", "pc": 1, "ph": 1, "stepsPc": ["Лучшее слоумо снимается заранее: 50–120 кадров в секунду. Тогда замедление в 2–4 раза будет плавным.", "Правый клик по клипу → «Скорость/Продолжительность» (Cmd/Ctrl+R) → например, 50%.", "Там же «Интерполяция времени» → «Оптический поток» — Премьер дорисует недостающие кадры.", "Или плагин КК → «Исправить» → «Слоумо 50%» / «25%»."], "stepsPh": ["«Скорость» → «Обычная» → 0,5x (или 0,25x для съёмки 120 кадров).", "Включи «Плавное замедление» / оптический поток, если есть.", "Плавный вход в замедление: «Скорость» → «Кривая»."]}, {"id": "audiocut", "n": "Кривая склейка по звуку", "d": "щелчок, обрывок слова, «вдох» на стыке", "pc": 1, "ph": 1, "stepsPc": ["Режь в паузе между словами, а не посреди звука: смотри на волну (график звука на дорожке).", "На стык звука поставь короткий переход «Постоянная мощность» (Cmd/Ctrl+Shift+D), 2–4 кадра.", "Или плагин КК: плейхед на стык → «Исправить» → «Мягкая склейка звука».", "Слышен резкий вдох перед фразой — подрежь или убавь громкость ключами."], "stepsPh": ["Режь в тишине между словами.", "«Громкость» → «Затухание»: появление и исчезновение по 0,1–0,2 с на стыке.", "Слышен щелчок — сдвинь точку реза на пару кадров."]}, {"id": "loud", "n": "Громкость: голос до −12 дБ", "d": "как выставить уровни, чтобы голос был слышно, а музыка не мешала", "pc": 1, "ph": 1, "stepsPc": ["Открой шкалу громкости: «Окно» → «Индикаторы звука». Это столбик справа от таймлайна: зелёный — тихо, жёлтый — громко, красный — перегруз.", "Голос: столбик в среднем около −12 дБ — это зелёно-жёлтая серединка. Самые громкие слова не выше −6 дБ. В красную зону не заходи никогда.", "Как поправить: правый клик по звуку → «Усиление звука» (Audio Gain) → «Корректировать усиление» на +3 или −3 дБ, пока не попадёшь в середину.", "Ровнее по всему ролику: «Окно» → «Основной звук» → выдели голос → «Диалог» → «Громкость» → «Автоматическое соответствие».", "Музыка под голосом: −20…−25 дБ. Звуковые эффекты (SFX) — заметно тише голоса, примерно −15…−18 дБ.", "Проверка: послушай в наушниках и через динамик ноутбука. Голос понятен — всё верно."], "stepsPh": ["Выдели голос (основное видео) — громкость 100 (или чуть выше, если тихо записано).", "Музыку убавь до 10–25, чтобы она была фоном и не перебивала речь.", "Звуковые эффекты — 20–40, тише голоса.", "Для ровного голоса: «Аудио» → «Шумоподавление» и «Нормализовать громкость» (если есть в версии).", "Проверь в наушниках и через динамик телефона на средней громкости."]}, {"id": "size", "n": "Размер под площадку", "d": "чтобы ролик не обрезался и не был с чёрными полосами", "pc": 1, "ph": 1, "stepsPc": ["Самый быстрый способ — плагин КК → «Секвенция» (эпизод — это таймлайн проекта) → нужный формат.", "Вручную: сверху меню «Эпизод» → «Настройки эпизода…».", "«Размер кадра»: вертикаль Reels/TikTok/Shorts — 1080 по горизонтали × 1920 по вертикали. Горизонталь YouTube — 1920 × 1080 (или 3840 × 2160 для 4K). Пост 4:5 — 1080 × 1350.", "«Пропорции пикселей» — «Квадратные пиксели (1,0)». «Частота кадров» — как у исходника (обычно 25 или 30).", "Нажми ОК. Если клипы стали меньше кадра — выдели их → правый клик → «Масштабировать до размера кадра» или плагин КК → «Убрать чёрные рамки».", "При экспорте (Cmd/Ctrl+M) проверь, что размер стоит «как у эпизода»."], "stepsPh": ["Внизу «Формат» (или «Соотношение») → 9:16 для Reels/TikTok/Shorts, 16:9 для YouTube, 4:5 для поста.", "Если видео с другими пропорциями — разведи его пальцами на весь экран или выбери «Фон» → «Размытие», чтобы не было чёрных полос.", "При экспорте выбери 1080p и 30 кадров."]}, {"id": "sd", "n": "Саунд-дизайн для акцента", "d": "саунд-дизайн — звуки, которые подчёркивают действия в кадре: «вжух», клик, удар", "pc": 1, "ph": 1, "stepsPc": ["Звук ставь на 1–2 кадра раньше события (вжух — на переход, клик — на появление текста).", "Громкость — по шпаргалке «Громкость»: эффекты тише голоса.", "Акцентов немного: 3–6 на рилс. Звук «перебивает» голос — он слишком громкий.", "Где брать звуки — Mixkit, Pixabay, Freesound (с лицензией CC0), Artlist."], "stepsPh": ["«Аудио» → «Звуковые эффекты» или свой файл.", "Поставь звук на 1–2 кадра раньше события.", "Громкость звука — тише голоса (20–40).", "Проверь в наушниках и через динамик."]}, {"id": "fontpair", "n": "Пара шрифтов: основной + акцентный", "d": "чтобы акцент читался — кириллица и латиница", "pc": 1, "ph": 1, "steps": ["Акцентный шрифт — характерный: жирный дисплейный, рукописный или моноширинный (все буквы одной ширины). Основной — спокойный и читаемый.", "Акцент должен заметно отличаться: другой вес, ширина или стиль. Два похожих шрифта — ошибка.", "Размер акцента в 1,5–2 раза больше основного текста.", "Не больше двух шрифтов в одном ролике.", "Проверь кириллицу и латиницу: «Привет Hello 2026».", "Готовые пары — в каждом стилевом наборе пака."]}, {"id": "flicker", "n": "Мерцание от ламп", "d": "что делать, если кадр «моргает»", "pc": 1, "ph": 1, "steps": ["Причина — лампы мигают с частотой сети (50 Гц), а выдержка камеры (время, за которое снимается кадр) с ней не совпала.", "При съёмке: выдержка 1/50 или 1/100 для 25/50 кадров. На телефоне — приложение с ручной выдержкой, например Blackmagic Camera.", "Если уже снято: в Премьере попробуй эффект «Эхо» с маленьким временем или положи копию клипа сверху со сдвигом на 1 кадр и непрозрачностью 50%.", "Профессионально — плагин «Flicker Free» (платный) или «Deflicker» в DaVinci Resolve Studio.", "Не лечится — обрежь кусок или закрой его графикой."]}, {"id": "move", "n": "Перенос CapCut ↔ Премьер", "d": "что переносится, а что нет", "pc": 1, "ph": 1, "steps": ["Проект CapCut в Премьере не откроется (и наоборот) — переносятся только файлы.", "Начала в CapCut, доделываешь в Премьере: экспортируй куски в максимальном качестве без субтитров и эффектов, которые будешь делать в Премьере.", "Из Премьера в CapCut: экспорт H.264 1080×1920 с высоким битрейтом (количеством данных в секунду — чем больше, тем чётче), дальше доделка на телефоне.", "Шрифты, звуки и наборы КК одинаковые в обеих программах — стиль сохранится."]}, {"id": "music", "n": "Музыка под атмосферу", "d": "чтобы трек не был «нейтральным»", "pc": 1, "ph": 1, "steps": ["Определи настроение ролика одним словом: нежно, драйв, хипстерски, кино, бизнес.", "Ищи трек по этому слову в Pixabay Music, Uppbeat или Artlist — с фильтром по настроению и темпу.", "Склейки ставь на сильные доли (удары в музыке). Темп трека = темп монтажа.", "Для рекламы и бизнеса — музыка без авторских прав или с купленной лицензией. Тренды из TikTok для клиента — риск блокировки.", "В каждом стилевом наборе есть подборка «Музыка по настроению»."]}, {"id": "export", "n": "Экспорт без потери качества", "d": "чтобы площадка не превратила ролик в «мыло»", "pc": 1, "ph": 1, "stepsPc": ["«Файл» → «Экспорт» → «Медиаданные» (Cmd/Ctrl+M). Формат — H.264.", "Размер — как у эпизода, частота кадров — как у исходника.", "Битрейт: «VBR, 1 проход», целевой 16–20 Мбит/с для 1080p, 40–60 — для 4K.", "Звук: AAC, 320 кбит/с, 48 кГц.", "Файл называй понятно: Клиент_Ролик_v2.mp4."], "stepsPh": ["«Экспорт» → разрешение 1080p (или 2K/4K, если снято в 4K), частота 30.", "Битрейт «Выше» или «Рекомендуемый» — не «Ниже».", "В Instagram включи в настройках «Загружать в высоком качестве»."]}, {"id": "capcutbugs", "n": "Баги CapCut: не экспортирует, лагает, плывут субтитры", "d": "что делать, когда телефон «сопротивляется»", "ph": 1, "stepsPh": ["Не экспортирует или вылетает: освободи память — нужно в 2–3 раза больше места, чем весит ролик. Закрой другие приложения, перезагрузи телефон.", "Всё ещё не экспортирует: поставь 1080p и 30 кадров вместо 4K/60, выключи «Smart HDR», обнови CapCut.", "Не помогло: «Дублировать» проект и экспортируй копию. Или экспортируй ролик двумя частями и склей их.", "Лагает просмотр: в настройках поставь качество предпросмотра пониже. Очисти кэш: профиль → настройки → «Очистить кэш» (проекты не удаляются).", "Плывут субтитры: делай автосубтитры в САМОМ КОНЦЕ, когда склейка окончательная. Если после этого резала видео — удали субтитры и создай заново.", "Не включай и не выключай туда-обратно синхронизацию (привязку) субтитров к видео — из-за этого они съезжают. После любой правки проверь синхрон в начале, середине и конце.", "Проект «битый» и не открывается — обнови приложение; если не помогло, собери ролик заново из сохранённых исходников (поэтому храни их отдельно)."]}, {"id": "keys", "n": "Ключи (ключевые кадры): основа", "d": "ключ — точка, где ты задаёшь положение, размер или прозрачность; между ключами программа плавно двигает объект", "pc": 1, "ph": 1, "stepsPc": ["Выдели клип → «Элементы управления эффектами» → «Движение».", "Поставь плейхед (бегунок времени) в начало движения, нажми секундомер рядом с «Положение» или «Масштаб» — появится первый ключ.", "Перемести плейхед дальше и измени значение — появится второй ключ. Между ними объект будет двигаться.", "Плавность: выдели оба ключа → правый клик → «Временная интерполяция» → «Безье». Открой стрелку слева у параметра — увидишь график скорости, тяни «усики», чтобы движение мягко начиналось и заканчивалось.", "Быстрее: плагин КК → «Плавность» — готовые кривые на выбранные ключи."], "stepsPh": ["Выдели клип, поставь бегунок в начало движения, нажми ромбик «◇+» — это первый ключ.", "Сдвинь бегунок, измени размер или положение пальцами — второй ключ появится сам.", "Нажми на ключ → «Кривая» (график) → выбери «Плавно» / «Ease In/Out», чтобы движение не было резким.", "Чтобы удалить ключ — встань на него и нажми ромбик ещё раз."]}, {"id": "zoomface", "n": "Эффектный наезд на лицо", "d": "плавное «дыхание» камеры к лицу — сразу дороже кадр", "pc": 1, "ph": 1, "stepsPc": ["Ключ 1 в начале клипа: «Масштаб» 100.", "Ключ 2 через 1,5–3 с: «Масштаб» 115–125. Одновременно сдвинь «Положение», чтобы лицо осталось в центре.", "Оба ключа → «Безье», на графике сделай медленный старт и медленный финиш.", "Акцентный вариант: третий ключ через 4 кадра после слова-акцента с «Масштабом» +10% — резкий «толчок» к лицу.", "Готовое: плагин КК → «Камера» → «Наезд»."], "stepsPh": ["Ключ в начале клипа — размер как есть.", "Ключ через 2 секунды — разведи пальцами, увеличь на 15–25%, лицо держи в центре.", "Ключ → «Кривая» → «Плавно».", "Для акцента — ещё один ключ на ударном слове с резким увеличением."]}, {"id": "blurtext", "n": "Текст выезжает с размытием", "d": "трендовое появление: текст «влетает» из размытия", "pc": 1, "ph": 1, "stepsPc": ["На текст: «Эффекты» → «Преобразовать» (Transform). Сними галочку «Использовать угол затвора композиции», «Угол затвора» — 180–360: появится смаз движения.", "В «Преобразовать»: ключ «Положение» — текст ниже на 80 пикселей, через 8–10 кадров — на месте. «Непрозрачность» 0 → 100.", "Добавь «Размытие по Гауссу»: ключ 40 → 0 за те же кадры.", "Все ключи → «Безье», быстрый старт и мягкий финиш.", "Почти то же одной кнопкой: плагин КК → «Текст» → «Подъём»."], "stepsPh": ["Выдели текст → «Анимация» → «Вход» → «Размытие» или «Подъём» — быстрый вариант.", "Вручную: ключ в начале — текст ниже и прозрачность 0; ключ через 0,3 с — на месте и 100.", "«Эффекты» → «Размытие»: ключ сильное → 0 за то же время.", "Ключи → «Кривая» → «Плавно»."]}, {"id": "flip3d", "n": "3D-переворот карточки", "d": "карточка или фото переворачивается, как в айфоне", "pc": 1, "ph": 1, "stepsPc": ["Положи картинку на дорожку выше видео → «Эффекты» → «Базовая 3D».", "Ключ «Поворот» (по горизонтали) 0° → через 10 кадров 90°. Здесь смени картинку (склейка) и продолжи: 90° → 0° у второй картинки.", "Добавь «Расстояние до изображения» ключ 0 → 30 → 0 — карточка будто отодвигается при перевороте.", "Ключи → «Безье» для мягкости."], "stepsPh": ["Выдели клип → «Анимация» → «Комбо» → эффекты с 3D-поворотом — быстрый вариант.", "Вручную: ключ — размер 100; середина — сузь картинку по ширине почти до полоски (сожми двумя пальцами по горизонтали); следующий ключ — снова 100 уже с другой картинкой.", "Ключи → «Кривая» → «Плавно»."]}, {"id": "maskreveal", "n": "Текст появляется из-за линии (маска-шторка)", "d": "маска — область, внутри которой видно объект; снаружи он скрыт", "pc": 1, "ph": 1, "stepsPc": ["Текст на дорожке → «Непрозрачность» → нарисуй прямоугольную маску вокруг места, где текст должен быть виден.", "Ключ «Положение» текста: начало — текст ниже маски (его не видно), через 10 кадров — на месте.", "Ключи → «Безье». Текст будто выезжает из-за невидимой линии.", "Дополнительно: тонкая линия-плашка из набора на месте края маски."], "stepsPh": ["Выдели текст → «Маска» → «Линейная», поставь линию под текстом, «Инвертировать», если нужно.", "Ключ на тексте: начало — текст ниже линии, через 0,3 с — на месте.", "Ключи → «Кривая» → «Плавно»."]}, {"id": "track", "n": "Текст следует за объектом", "d": "трекинг — программа сама «следит» за движущимся объектом", "pc": 1, "ph": 1, "stepsPc": ["В Премьере текст сам за объектом не ходит — двигаем ключами.", "Поставь ключи «Положение» текста каждые 5–10 кадров так, чтобы он оставался рядом с объектом.", "Ключи → «Временная интерполяция» → «Безье» — движение станет плавным.", "Сложное движение быстрее сделать в After Effects (трекинг) и вернуть в Премьер."], "stepsPh": ["Выдели текст или стикер → «Трекинг» (Tracking).", "Поставь рамку на объект, за которым следить (лицо, рука, товар) → «Начать».", "Подожди анализ — текст будет двигаться вместе с объектом.", "Если сбился — сократи участок или поставь рамку на более контрастную деталь."]}, {"id": "ramp", "n": "Рывок скорости (speed ramp)", "d": "видео резко ускоряется и снова замедляется — динамично на переходах", "pc": 1, "ph": 1, "stepsPc": ["Правый клик по клипу → «Показать ключевые кадры клипа» → «Ремаппинг времени» → «Скорость».", "С Cmd/Ctrl кликни по линии скорости — поставь две точки. Подними линию между ними (например, 300%).", "Раздвинь половинки точек — переход скорости станет плавным, а не ступенькой.", "Красиво на смене сцены: разгон перед склейкой и замедление после."], "stepsPh": ["Выдели клип → «Скорость» → «Кривая» → готовые: «Монтаж», «Герой», «Пуля», «Скачок».", "Своя кривая: «Пользовательская» → тяни точки вверх (быстрее) и вниз (медленнее).", "Включи «Плавное замедление», если есть."]}, {"id": "workflow", "n": "Порядок монтажа: по шагам", "d": "как монтировать быстрее и не переделывать", "pc": 1, "ph": 1, "note": "Порядок может отличаться от проекта к проекту, но главное правило одно: закончи шаг — переходи к следующему. Не прыгай туда-обратно: так ломается синхрон, теряются файлы и уходят часы.", "stepsPc": ["Подготовка: создай папки проекта (см. «Рабочее место»), скачай всё от клиента, импортируй в Премьер, разложи по папкам (корзинам) внутри проекта.", "Отсмотр: просмотри исходники и отметь хорошие куски маркерами (клавиша M).", "Черновая сборка: склей ролик по смыслу и сценарию, без красоты. Сначала история — потом эффекты.", "Ритм: подгони склейки под музыку и темп, убери лишние паузы.", "Звук: чистка голоса, уровни (шпаргалка «Громкость»), музыка.", "Графика: тексты, плашки, анимации, переходы (плагин КК и наборы).", "Субтитры: только когда склейка окончательная. Иначе их придётся переделывать.", "Цвет: цветокоррекция одним корректирующим слоем на весь ролик.", "Финальный звук: звуковые эффекты (SFX), проверка громкости.", "Экспорт и чек-лист перед сдачей.", "Ускорение: горячие клавиши (гайд в программе), плагин КК, сохранённые пресеты, прокси для тяжёлого 4K."], "stepsPh": ["Подготовка: собери все файлы в один альбом в «Фото» (или в папку), назови проект понятно.", "Черновая сборка: склей по смыслу, без эффектов.", "Ритм и музыка.", "Звук: громкость голоса и музыки, шумоподавление.", "Графика: тексты, стикеры, переходы, наборы КК.", "Субтитры — в САМОМ КОНЦЕ, когда больше ничего не режешь. Не включай и не выключай их синхронизацию туда-обратно.", "Цвет и фильтры.", "Проверка синхрона и экспорт.", "Ускорение: шаблоны, копирование эффектов (скопировать → вставить на другой клип), готовые наборы КК."]}, {"id": "workspace", "n": "Рабочее место: папки и порядок", "d": "чтобы файлы никогда не терялись, даже через год", "pc": 1, "ph": 1, "tree": ["📁 Клиенты", "  📁 Анна_Бьюти_2026-10", "    📁 01_Исходники        ← всё от клиента: видео, фото", "    📁 02_Звук             ← музыка, голос, звуковые эффекты", "    📁 03_Графика          ← PNG, наборы КК, логотип, шрифты", "    📁 04_Проект           ← файл Премьера / копии проекта", "    📁 05_Экспорт          ← v1, v2, финал", "    📁 06_Документы        ← бриф, договор, правки", "  📁 Иван_Недвижимость_2026-11", "📁 Мои_ресурсы           ← наборы КК, шрифты, звуки — общие для всех проектов"], "note": "Зачем: когда проектов много, файлы путаются, Премьер теряет ссылки на видео («медиаданные в автономном режиме»), а нужную версию не найти. Один клиент — одна папка, внутри всегда одинаковые подпапки.", "stepsPc": ["Создай папку клиента ДО импорта и сохрани в неё файл проекта (04_Проект).", "Копируй исходники в 01_Исходники и только потом импортируй в Премьер. После импорта файлы не переименовывай и не перемещай — иначе Премьер их потеряет.", "Внутри Премьера сделай такие же папки (корзины): Исходники, Звук, Графика, Эпизоды.", "Называй версии понятно: Анна_рилс1_v2.mp4, а не final_final3.", "Автосохранение: «Настройки» → «Автосохранение» — каждые 5 минут.", "Проект сдан: «Файл» → «Управление проектом» → собрать всё в одну папку, затем архив на диск или в облако."], "stepsPh": ["На телефоне: альбом в «Фото» на каждого клиента, туда же скачивай файлы.", "Проекты в CapCut называй: Клиент_ролик_дата.", "Готовые ролики — в отдельный альбом «Экспорт», старые черновики удаляй.", "Раз в неделю — исходники и экспорт в облако (iCloud, Google Диск, Яндекс Диск), чтобы не потерять при сбое CapCut."]}, {"id": "speed", "n": "Как монтировать быстрее", "d": "приёмы, которые экономят часы", "pc": 1, "ph": 1, "steps": ["Работай по шагам (шпаргалка «Порядок монтажа»): законченный шаг → следующий.", "Горячие клавиши — гайд в программе. Хотя бы 10 главных: резать, удалить с заполнением, скорость, приблизить таймлайн.", "Не шлифуй первый черновик: сначала весь ролик целиком, потом детали.", "Повторяющиеся вещи — шаблоны: плагин КК, пресеты эффектов, сохранённые стили текста.", "Тяжёлые 4K-файлы — делай прокси (облегчённые копии для монтажа).", "Одинаковые эффекты — копируй и вставляй атрибуты (Премьер: Cmd/Ctrl+Alt+V; CapCut: «Копировать» → «Вставить эффект»).", "Перерыв каждые 1–1,5 часа: свежим глазом ошибки видно сразу."]}];
